        self.assertQueryError(
            "SELECT ?s ?o WHERE { { ?s knows ?o } UNION { FILTER(BOUND(?o)) } }",
            "分支",
        )

    def test_nested_union_rejected(self):
        self.assertQueryError(
            "SELECT ?s ?o WHERE {"
            " { { ?s knows ?o } UNION { ?s likes ?o } } UNION { ?s email ?o } }",
            "分支",
        )
        self.assertQueryError(
            "SELECT ?s ?o WHERE {"
            " { ?s knows ?o . UNION { ?s likes ?o } } UNION { ?s email ?o } }",
            "分支",
        )

    def test_optional_inside_branch_rejected(self):
